<script setup>
import { computed, onUnmounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, errorMessage } from '../api';
import { money, statusLabel, foodImage, reorder } from '../store';
const route = useRoute(); const router = useRouter();
const order = ref(null); const error = ref(''); const busy = ref(false); const nextStatus = ref('');
const admin = computed(()=>route.path.startsWith('/admin/'));
const steps = computed(()=>order.value?.order_type === 'delivery' ? ['pending','confirmed','preparing','ready','out_for_delivery','delivered','completed'] : ['pending','confirmed','preparing','ready','completed']);
const allowedStatuses = computed(()=>{
    if(!order.value) return [];
    const transitions={pending:['confirmed','cancelled'],confirmed:['preparing','cancelled'],preparing:['ready','cancelled'],ready:order.value.order_type === 'delivery' ? ['out_for_delivery','cancelled'] : ['completed','cancelled'],out_for_delivery:['delivered','cancelled'],delivered:['completed'],completed:[],cancelled:[]};
    return transitions[order.value.order_status] || [];
});
async function load() {try{order.value=(await api.get(`${admin.value ? '/admin' : ''}/orders/${route.params.id}`)).data.data;error.value='';if(!allowedStatuses.value.includes(nextStatus.value))nextStatus.value=allowedStatuses.value[0] || '';}catch(failure){error.value=errorMessage(failure);}}
async function updateStatus() {busy.value=true;try{await api.patch(`/admin/orders/${order.value.id}/status`,{order_status:nextStatus.value});await load();}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
async function updatePayment(status) {busy.value=true;try{await api.patch(`/admin/orders/${order.value.id}/payment`,{payment_status:status});await load();}catch(failure){error.value=errorMessage(failure);}finally{busy.value=false;}}
async function orderAgain() {busy.value=true;try{await reorder(order.value);await router.push('/cart');}finally{busy.value=false;}}
watch(()=>route.params.id,()=>{order.value=null;load();},{immediate:true});
const timer=setInterval(()=>{if(order.value && !busy.value && !['completed','cancelled'].includes(order.value.order_status)) load();},15000);
onUnmounted(()=>clearInterval(timer));
</script>
<template><div><router-link :to="admin ? '/admin/orders' : '/account/orders'" class="text-button">← All orders</router-link><div v-if="error" class="form-error" role="alert">{{ error }} <button @click="load">Try again</button></div><template v-if="order"><div class="panel"><div class="eyebrow">{{ route.query.placed ? 'THANK YOU · YOUR ORDER HAS BEEN RECEIVED' : 'FROM OUR KITCHEN TO YOUR TABLE' }}</div><div class="section-heading"><h2 class="order-number">{{ order.order_number }}</h2><span class="status-badge" :data-status="order.order_status">{{ statusLabel(order.order_status) }}</span></div><p>{{ new Date(order.created_at).toLocaleString() }} · {{ statusLabel(order.order_type) }}</p><div v-if="order.order_status === 'cancelled'" class="form-error">This order was cancelled. Contact the restaurant if you have questions about payment.</div><ol v-else class="order-timeline"><li v-for="step in steps" :key="step" :class="{done:steps.indexOf(step) <= steps.indexOf(order.order_status), current:step === order.order_status}"><span>{{ steps.indexOf(step) <= steps.indexOf(order.order_status) ? '✓' : '○' }}</span>{{ statusLabel(step) }}</li></ol><p class="small-note">Status refreshes every 15 seconds while this page is open.</p><form v-if="admin && allowedStatuses.length" @submit.prevent="updateStatus" class="inline-controls"><label>Next status<select v-model="nextStatus"><option v-for="status in allowedStatuses" :key="status" :value="status">{{ statusLabel(status) }}</option></select></label><button class="button button-small" :disabled="busy">Update status</button></form></div><div class="order-detail-grid"><div class="panel"><h3>What’s in your order</h3><article v-for="item in order.items" :key="item.id" class="order-detail-item"><img :src="foodImage(item.image,200)" :alt="item.product_name"><div><strong>{{ item.quantity }} × {{ item.product_name }}</strong><p>{{ [item.variation_name,...item.addons.map(addon=>addon.name)].filter(Boolean).join(' · ') }}</p><small>{{ money(item.unit_price) }} each</small></div><strong>{{ money(item.total) }}</strong></article><button v-if="!admin && ['completed','delivered'].includes(order.order_status)" class="button" @click="orderAgain" :disabled="busy">Order again ↗</button><div class="order-contact"><h3>{{ order.order_type === 'delivery' ? 'Delivery details' : 'Pickup details' }}</h3><p>{{ order.customer_name }} · {{ order.customer_phone }}<br>{{ order.customer_email }}</p><p v-if="order.delivery_address">{{ order.delivery_address.address }}<br>{{ order.delivery_address.area }}, {{ order.delivery_address.city }}<br>{{ order.delivery_address.landmark }}<br>{{ order.delivery_address.instructions }}</p><p v-if="order.customer_note">Note: {{ order.customer_note }}</p></div></div><aside class="panel"><h3>Order summary</h3><dl class="summary-list"><div><dt>Subtotal</dt><dd>{{ money(order.subtotal) }}</dd></div><div><dt>Discount {{ order.coupon_code }}</dt><dd>− {{ money(order.discount) }}</dd></div><div><dt>Delivery</dt><dd>{{ money(order.delivery_fee) }}</dd></div><div><dt>Tax</dt><dd>{{ money(order.tax) }}</dd></div><div class="summary-total"><dt>Total</dt><dd>{{ money(order.total) }}</dd></div></dl><p>{{ statusLabel(order.payment_method) }}<br>Payment: <strong>{{ statusLabel(order.payment_status) }}</strong></p><div v-if="admin" class="row-actions"><button v-if="order.payment_status === 'pending' && order.order_status !== 'cancelled'" class="button button-small" @click="updatePayment('paid')" :disabled="busy">Record cash received</button><button v-if="order.payment_status === 'paid'" class="text-button" @click="updatePayment('refunded')" :disabled="busy">Record refund</button></div><p v-if="admin" class="small-note">Payment actions record cash handling; they do not transfer money.</p><h3 class="history-heading">Status history</h3><p v-for="(event,index) in order.status_history" :key="index" class="small-note">{{ statusLabel(event.status) }} · {{ new Date(event.at).toLocaleString() }}</p></aside></div></template><p v-else-if="!error">Loading your order…</p></div></template>
